      |(rule ((root-plug-input focus))
      |      ((cursor (RootCtx) focus)
      |       (plug-source (RootCtx) focus)
      |       (context-path (RootCtx) (Eps))
      |       (plugged (RootCtx) focus focus)))
      |(rule ((= ctx (PatchFrameCtx parent item original)) (context-path parent path))
      |      ((context-path ctx (Concat path (Item item)))))
      |(rule ((cursor ctx focus) (context-path ctx path))
      |      ((cursor-path ctx focus path)))
      |(rule ((= ctx (PatchFrameCtx parent item original))
