      |(let $pa (Item "a"))
      |(let $pb (Item "b"))
      |(let $pc (Item "c"))
      |(let $seps (Singleton (Eps)))
      |(let $sa (Singleton $pa))
      |(let $sb (Singleton $pb))
      |(let $parent (UnionOp (TrieZ $sa) (TrieZ $sb)))
      |(let $child_a (Child "a" $parent))
      |(let $child_b (Child "b" $parent))
      |(let $ctx_a (PatchFrameCtx (RootCtx) "a" $parent))
      |(let $ctx_b (PatchFrameCtx (RootCtx) "b" $parent))
