      |(cursor $ctx_a $child_a)
      |(cursor $ctx_b $child_b)
      |(cursor $nested_ctx_a $nested_child_a)
      |(cursor $nested_ctx_ab $nested_child_b)
      |
      |(run 96)
      |
      |(check (= $child_a (TrieZ $seps)))
      |(check (= $child_b (TrieZ $seps)))
      |(check (= $nested_child_a (TrieZ (Singleton $path_bc))))
      |(check (= $nested_child_b (TrieZ (Singleton $pc))))
