      |(check (next-sibling-move $ctx_a $child_a $ctx_b $child_b))
      |(check (previous-sibling-move $ctx_b $child_b $ctx_a $child_a))
      |(check (plugged $sibling_ctx_b $sibling_focus_b $sibling_updated_after_b))
